import java.io.IOException;
import java.io.PrintWriter;
import java.sql.*;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
// Add Apache Commons Text to your classpath for HTML escaping:
// implementation "org.apache.commons:commons-text:1.11.0"
import org.apache.commons.text.StringEscapeUtils;

public class LoginServletGood extends HttpServlet {
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        // Minimal server-side validation to reduce abuse and unexpected input
        String username = request.getParameter("username");
        String password = request.getParameter("password");
        if (username == null || password == null || username.length() > 64 || password.length() > 128) {
            response.sendError(400, "Invalid input");
            return;
        }

        // Use parameterized queries to prevent SQL injection (not vulnerable)
        String sql = "SELECT id, username FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/appdb", "appuser", "apppass");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username);
            ps.setString(2, password);
            // Optionally limit query execution time
            ps.setQueryTimeout(5);

            try (ResultSet rs = ps.executeQuery()) {
                response.setContentType("text/html; charset=UTF-8");
                PrintWriter out = response.getWriter();
                if (rs.next()) {
                    // Escape output to prevent XSS when reflecting user-controlled data
                    String safeUsername = StringEscapeUtils.escapeHtml4(username);
                    out.println("<h1>Welcome, " + safeUsername + "</h1>");
                } else {
                    out.println("Invalid login");
                }
            }
        } catch (SQLException e) {
            response.sendError(500, "Database error");
        }
    }
}

